<?php
namespace App\Http\Controllers;
use App\Models\{KioskToken,Reservation,Guest};
use App\Services\HotelService as Hotel;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Symfony\Component\Process\Process;
class KioskController extends Controller {
 public function issue(Reservation $reservation){abort_unless($reservation->status==='Confirmed',422);$token=strtoupper(bin2hex(random_bytes(8)));KioskToken::create(['reservation_id'=>$reservation->id,'token_hash'=>hash('sha256',$token),'expires_at'=>now()->addMinutes(30)]);Hotel::audit('kiosk.token-issued',$reservation->code);return ['code'=>$reservation->code,'verification_code'=>$token,'expires_at'=>now()->addMinutes(30)->toIso8601String()];}
 public function verify(Request $r){$v=$r->validate(['code'=>'required|string|max:40','verification_code'=>'required|string|max:50']);$t=KioskToken::where('token_hash',hash('sha256',$v['verification_code']))->whereNull('used_at')->where('expires_at','>',now())->first();if(!$t||$t->reservation_id!==Reservation::where('code',$v['code'])->value('id'))Hotel::fail('The reservation or verification code is invalid or expired.');$r->session()->regenerate();$r->session()->forget('kiosk_scan_review');$r->session()->put('kiosk_token',$t->id);$r->session()->put('kiosk_last_activity',now()->timestamp);return ['code'=>$v['code'],'guest'=>Guest::findOrFail(Reservation::findOrFail($t->reservation_id)->guest_id)->only('name','birth_date','address')];}
 private function token(Request $r):KioskToken {$last=$r->session()->get('kiosk_last_activity',0);abort_if(now()->timestamp-$last>300,419,'Kiosk session expired.');$t=KioskToken::whereKey($r->session()->get('kiosk_token'))->whereNull('used_at')->where('expires_at','>',now())->firstOrFail();$r->session()->put('kiosk_last_activity',now()->timestamp);return $t;}
 public function scan(Request $r){$this->token($r);$r->validate(['image'=>'required|file|mimes:jpg,jpeg,png|max:5120']);$binary=config('hrms.ocr_binary');$path=$r->file('image')->store('ocr-tmp','local');try{$command=$binary&&is_file($binary)?[$binary,storage_path('app/private/'.$path),'stdout','-l','eng']:[config('hrms.node_binary'),base_path('scripts/ocr.cjs'),storage_path('app/private/'.$path)];$p=new Process($command,base_path());$p->setTimeout(30);$p->mustRun();$text=mb_substr($p->getOutput(),0,8000);preg_match('/(?:name)\s*[:\-]\s*([^\r\n]+)/i',$text,$name);preg_match('/(?:address)\s*[:\-]\s*([^\r\n]+)/i',$text,$address);preg_match('/(?:birth|dob)[^\r\n]*?(\d{4}-\d{2}-\d{2})/i',$text,$birth);if(empty($name[1]))Hotel::fail('A supported name field could not be read. Retry the scan or ask the front desk for assistance.');$r->session()->put('kiosk_scan_review',true);return ['text'=>$text,'fields'=>['name'=>trim($name[1]??''),'address'=>trim($address[1]??''),'birth_date'=>$birth[1]??'']];}finally{\Illuminate\Support\Facades\Storage::disk('local')->delete($path);}}
 public function complete(Request $r){$token=$this->token($r);if(!$r->session()->get('kiosk_scan_review'))Hotel::fail('Scan a supported ID before completing check-in, or ask the front desk for assistance.');$v=$r->validate(['name'=>'required|string|max:180','birth_date'=>'nullable|date|before:today','address'=>'nullable|string|max:1000','reviewed'=>'accepted']);return DB::transaction(function()use($r,$token,$v){$t=KioskToken::lockForUpdate()->findOrFail($token->id);if($t->used_at||$t->expires_at->isPast())Hotel::fail('This check-in request has expired or was already used.');$reservation=Reservation::findOrFail($t->reservation_id);$guest=Guest::findOrFail($reservation->guest_id);if(mb_strtolower(trim($v['name']))!==mb_strtolower(trim($guest->name)))Hotel::fail('The guest name does not match. Please ask the front desk to review registration.');$guest->update(collect($v)->only('birth_date','address')->all());Hotel::checkIn($reservation);$t->update(['used_at'=>now()]);$r->session()->forget(['kiosk_token','kiosk_last_activity','kiosk_scan_review']);return ['ok'=>true,'code'=>$reservation->code];});}
 public function clear(Request $r){$r->session()->forget(['kiosk_token','kiosk_last_activity','kiosk_scan_review']);return ['ok'=>true];}
}
